// Sample incoming messages (stand-ins for real emails or form submissions)
const messages = [
  { from: 'maria@acmeco.com', subject: 'Interested in a demo',
    body: "Hi, we're a 40-person logistics company looking to automate our invoicing. Can we set up a call next week?" },
  { from: 'dave@randomuser.net', subject: 'Login not working',
    body: "I can't log into my account since this morning. It says my password is invalid but I didn't change it." },
  { from: 'billing@vendorco.com', subject: 'Invoice #4471 attached',
    body: 'Please find attached invoice #4471 for services rendered in October. Payment due in 30 days.' },
  { from: 'promo@cheapdeals.biz', subject: 'YOU WON!!! Claim your prize',
    body: 'Congratulations!!! Click here to claim your free gift card now!!! Limited time offer!!!' }
];

function classify(m) {
  const text = (m.subject + ' ' + m.body).toLowerCase();
  if (/won|congratulations|free gift|claim your prize|click here/.test(text)) return 'spam';
  if (/invoice|payment due|amount due|billing/.test(text)) return 'invoice';
  if (/can.?t log|cannot log|not working|error|issue|broken|password|bug/.test(text)) return 'support';
  if (/demo|pricing|interested|quote|call|automate|looking to/.test(text)) return 'sales lead';
  return 'other';
}

function summarize(m) {
  const first = m.body.split(/[.!?]/)[0].trim();
  return first.length ? first : m.subject;
}

return messages.map(m => ({
  json: {
    from: m.from,
    subject: m.subject,
    body: m.body,
    category: classify(m),
    summary: summarize(m),
    received_at: new Date().toISOString()
  }
}));

