// Find Claude's JSON reply anywhere in the item, whatever shape it comes back in
function findReply(o) {
  if (typeof o === 'string' && o.includes('"category"')) return o;
  if (o && typeof o === 'object') {
    for (const v of Object.values(o)) {
      const r = findReply(v);
      if (r) return r;
    }
  }
  return null;
}

const originals = $('Classify & Summarize').all();

return $input.all().map((item, i) => {
  const text = findReply(item.json) || '';
  let ai;
  try {
    ai = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  } catch (e) {
    ai = { category: 'other', priority: 'medium', summary: '(could not read AI reply)', suggested_reply: '' };
  }
  const orig = originals[i].json;
  return {
    json: {
      received_at: orig.received_at,
      from: orig.from,
      subject: orig.subject,
      category: ai.category,
      priority: ai.priority,
      summary: ai.summary,
      suggested_reply: ai.suggested_reply,
    },
  };
});
